for (const re of pats){ console.log('\n########', re); let n=0; for (const c of calls) { const code=c.code; const m=code.search(re); if(m<0) continue; if(n++>=3) break; console.log(`--[${c.thread}#${c.i}] ${c.label} err=${c.isError}`); console.log(code.slice(Math.max(0,m-250), m+300)); } }
EOF
node /tmp/ctx.mjs

